(function(){
  // Stop Greenhouse React bundle from hydrating and replacing the SSR DOM with "Page not found".
  const origAppend = Element.prototype.appendChild;
  const origCreate = Document.prototype.createElement;
  // Block any <script> whose src points at greenhouse CDN bundles.
  const blockedHosts = ['job-boards.cdn.greenhouse.io', 'cdn.greenhouse.io'];
  Document.prototype.createElement = function(tag) {
    const el = origCreate.call(this, tag);
    if (String(tag).toLowerCase() === 'script') {
      Object.defineProperty(el, 'src', {
        set(v) {
          if (blockedHosts.some(h => String(v).includes(h))) { return; }
          el.setAttribute('src', v);
        },
        get() { return el.getAttribute('src'); }
      });
    }
    return el;
  };
  // Also strip <script src=...> tags already in HTML before parser runs them.
  const obs = new MutationObserver(muts => {
    for (const m of muts) for (const n of m.addedNodes) {
      if (n.tagName === 'SCRIPT' && blockedHosts.some(h => String(n.src||'').includes(h))) {
        n.type = 'javascript/blocked';
        n.remove();
      }
    }
  });
  obs.observe(document, {childList:true, subtree:true});
})();

