() => {
  // Demonstrate React-Select fallback technique: drive the underlying input via
  // a synthetic native value setter so React (if running) would observe the change.
  // Then dispatch input + change events so React-Select's onChange handlers would fire.
  const setNative = (el, val) => {
    const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    setter.call(el, val);
    el.dispatchEvent(new Event('input', { bubbles: true }));
    el.dispatchEvent(new Event('change', { bubbles: true }));
  };
  const country = document.getElementById('country');
  const question = document.getElementById('question_14364081008');
  const target = country || question;
  setNative(target, 'Job board');
  return {
    targetId: target.id,
    targetClass: target.className,
    valueAfter: target.value,
    note: 'No native <select> in form; nearest React-Select combobox driven via synthetic native value setter + input/change dispatch (React fast-path).'
  };
}
